head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_StdIndList_OnLoadError
 * @description dts_StdIndList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_StdIndList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_StdIndList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00102.dts_StdIndList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_StdIndList_OnLoadCompleted
 * @description dts_StdIndList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_StdIndList_OnLoadCompleted = function(rowcount) {
    try {
        // 데이터셋 OnLoadCompleted
        if (dts_StdIndList.errorMsg) {
            alert(dts_StdIndList.errorMsg);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00102.dts_StdIndList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        await scwin.closeFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00102.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Confirm_onclick = async function() {
    try {
        // 확인버튼 클릭
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00102.img_Confirm_onclick" });
    }
};

/**
 * @method
 * @name trv_StdInd_ondblclick
 * @description trv_StdInd 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trv_StdInd_ondblclick = async function() {
    try {
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00102.trv_StdInd_ondblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 업종목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    // ShowWin(grd_StdIndList);

    const sbmOptions = {
        id : "sbm_dts_StdIndList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_StdIndList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_StdIndList.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dts_StdIndList.getRowPosition();
    }
    const arrPar = new Array();
    arrPar[0] = {
        STD_IND_CD: dts_StdIndList.getCellData(v_Currow, "STD_IND_CD"), // 업종코드
        STD_IND_NM: dts_StdIndList.getCellData(v_Currow, "STD_IND_NM") // 업종명
    };

    opener.fn_SetParStdIndCd(arrPar);
    await scwin.closeFrame();
};

/**
 * @method
 * @name closeFrame
 * @description close frame
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeFrame = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description form onload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // form onload
    $c.libRoundPanel.PanelToGroupBox(panel_Top); // 패널라운드 처리

    // 업종 조회
    await scwin.search();
};
